def load(p):return json.loads(Path(p).read_text())
def cell(a,arm,v,k,key):return (((a.get('arms') or {}).get(arm) or {}).get(v) or {}).get(k,{}).get(key)
def delta(a,b):return None if a is None or b is None else float(a)-float(b)
def main():
 ap=argparse.ArgumentParser(description='v48.71 OC-BORW boundary-localized history-reachability attribution');ap.add_argument('--feasibility-audit',type=Path,required=True);ap.add_argument('--trust-audit',type=Path,required=True);ap.add_argument('--truth-strata',type=Path,required=True);ap.add_argument('--v70-complete',type=Path,required=True);ap.add_argument('--v70-comparison',type=Path,required=True);ap.add_argument('--output',type=Path,required=True);x=ap.parse_args()
 a=load(x.feasibility_audit);tr=load(x.trust_audit);truth=load(x.truth_strata);v70=load(x.v70_complete);c70=load(x.v70_comparison)
 deltas={};source=[];select=[];safe=[];cert=[];main=[];nonfloor=[];factorial=[]
 for v in VARIANTS:
  deltas[v]={}
