   ke=delta(vals['K71_OCBORW'],vals['E70_OCCSOFT']);he=delta(vals['H71_BOUNDARY_LOCAL'],vals['E70_OCCSOFT']);je=delta(vals['J71_HISTORY_TUBE'],vals['E70_OCCSOFT']);kh=delta(vals['K71_OCBORW'],vals['H71_BOUNDARY_LOCAL']);kj=delta(vals['K71_OCBORW'],vals['J71_HISTORY_TUBE']);kb=delta(vals['K71_OCBORW'],vals['B_native']);interaction=None if any(z is None for z in (ke,he,je)) else ke-he-je
   deltas[v][k]={'K_minus_B_auc':kb,'H_minus_E70_auc':he,'J_minus_E70_auc':je,'K_minus_E70_auc':ke,'K_minus_H71_auc':kh,'K_minus_J71_auc':kj,'predictor_x_boundary_interaction_auc':interaction};source.append(kb is not None and kb>0)
